/**
 * Demo persona: six weeks of realistic history generated by running the REAL planner and
 * engine on a simulated learner. Clearly labelled as demo data in the UI, and removable in
 * one click. Lets judges and new users explore every dashboard immediately.
 */
import type { AIEvent } from './collaboration';
import { DIMENSION_IDS, getTask, taskForDimension } from './dimensions';
import { DEFAULT_PREFS, generateDailyPlan, type PlannerPrefs } from './planner';
import { createRng, uid } from './rng';
import { finalizeSession } from './session';
import { simulateRun, trueAbility, type SimUser } from './simulate';
import { applySession, createTwin, currentProfile, sessionPrior } from './twin';
import { clamp } from './stats';
import type { DailyPlan, Goal, SessionMode, SessionRecord, TwinState } from './types';

const DAY = 86_400_000;

export const DEMO_PERSONA: SimUser = {
  theta: { attention: 0.3, memory: -0.5, speed: 0.6, inhibition: 0.1, flexibility: -0.3, reasoning: 0.2 },
  growth: { attention: 0.5, memory: 1.1, speed: 0.3, inhibition: 0.5, flexibility: 0.9, reasoning: 0.6 },
  rtScale: 1,
  lapseRate: 0.03,
  interruptRate: 0.06,
};

export interface DemoData {
  twin: TwinState;
  sessions: SessionRecord[];
  goals: Goal[];
  plans: DailyPlan[];
  events: AIEvent[];
  prefs: PlannerPrefs;
}

export function buildDemoHistory(now: number, seed = 7): DemoData {
  const rng = createRng(seed);
  const start = startOfDay(now - 42 * DAY);
  let twin = createTwin(start);
  const sessions: SessionRecord[] = [];
  const events: AIEvent[] = [];
  const goals: Goal[] = [];
  const plans: DailyPlan[] = [];
  const done: Record<string, number> = {};
  const prefs: PlannerPrefs = { ...DEFAULT_PREFS, dailyMinutes: 10 };
  const evt = (type: AIEvent['type'], at: number, data?: AIEvent['data']) => events.push({ id: uid('ev_'), type, at, data });

  const run = (dim: string, mode: SessionMode, at: number, stateShift: number, opts: { predict?: boolean; planItemId?: string } = {}) => {
    const task = taskForDimension(dim);
    const prior = sessionPrior(twin, dim, at);
    const ability = trueAbility(DEMO_PERSONA, dim, done[dim] ?? 0) + rng.normal(0, 0.08);
    const res = simulateRun(task, DEMO_PERSONA, { mode, prior, ability, rng, startedAt: at, stateShift, challenge: prefs.challenge });
    const progress = (at - start) / (42 * DAY);
    const mood = clamp(Math.round(3.4 + stateShift * 3 + rng.normal(0, 0.8)), 1, 5);
    const energy = clamp(Math.round(3.3 + stateShift * 4 + rng.normal(0, 0.9)), 1, 5);
    const willPredict = opts.predict ?? rng.chance(0.45);
    const record = finalizeSession({
      id: uid('s_'),
      taskId: task.id,
      mode,
      startedAt: at,
      endedAt: res.endedAt,
      trials: res.trials,
      behaviour: { ...res.behaviour, input: rng.chance(0.7) ? 'keyboard' : 'mouse' },
      prior,
      selfReportBefore: rng.chance(0.6) ? { mood, energy } : undefined,
      deadlineFactor: 1.08,
      planItemId: opts.planItemId,
      demo: true,
    });
    if (willPredict) {
      // Over-confident at first, better calibrated with experience.
      const bias = 16 * (1 - progress) + 2;
      record.selfPrediction = clamp(Math.round(record.scoreAfter.score + bias + rng.normal(0, 6)), 5, 95);
      evt('self_prediction', at, { predicted: record.selfPrediction, actual: Math.round(record.scoreAfter.score) });
    }
    twin = applySession(twin, record);
    sessions.push(record);
    done[dim] = (done[dim] ?? 0) + 1;
    evt('session_completed', record.endedAt, {
      hints: task.id === 'pattern-logic' && rng.chance(0.3 - 0.2 * progress) ? 1 : 0,
      hintsAvailable: task.id === 'pattern-logic',
      reliability: record.quality.reliability,
    });
    // Session feedback from the coach; the learner opens "Why?" more often over time.
    const engaged = rng.chance(0.15 + 0.35 * progress);
    evt('coach_message', record.endedAt + 5000, { confidence: record.scoreAfter.confidence, engaged });
    if (engaged) evt('why_opened', record.endedAt + 20_000);
    if (record.affect.state === 'fatigued' || record.affect.state === 'strained') evt('break_suggested', record.endedAt + 5000, { taken: rng.chance(0.6) });
    return record;
  };

  // Day 0 — consent, calibration and the baseline check-in on all dimensions.
  const day0 = start + 9 * 3600_000;
  evt('consent_informed', day0 - 120_000);
  evt('privacy_reviewed', day0 - 60_000);
  let t = day0;
  for (const dim of DIMENSION_IDS) {
    const s = run(dim, 'assessment', t, 0.1, { predict: true });
    t = s.endedAt + 40_000;
  }

  let previous: DailyPlan | undefined;
  for (let d = 1; d <= 41; d++) {
    const dayStart = start + d * DAY;
    const weekday = new Date(dayStart).getDay();
    const inGap = d >= 22 && d <= 26; // a realistic break (exam week)
    const p = d >= 39 ? 1 : inGap ? 0.05 : weekday === 0 || weekday === 6 ? 0.45 : 0.8;

    // Goals and notable interactions happen whether or not the learner trains that day.
    const noon = dayStart + 12 * 3600_000;
    if (d === 7) {
      goals.push({ id: uid('g_'), kind: 'habit', target: 4, deadline: now + 21 * DAY, createdAt: noon, selfSet: true, note: 'Practise 4 days a week' });
      evt('goal_self_set', noon);
    }
    if (d === 14) {
      const mem = currentProfile(twin, noon).find((x) => x.id === 'memory')!;
      goals.push({ id: uid('g_'), kind: 'score', dimension: 'memory', target: Math.min(90, Math.round(mem.summary.score + 14)), deadline: now + 12 * DAY, createdAt: noon, selfSet: false });
      evt('goal_from_ai', noon);
    }
    if (d === 10) evt('clinical_query', noon, { acceptedRedirect: true });
    if (d === 12 || d === 27 || d === 38) evt('verify_challenge', noon, { found: d !== 12 });
    if (d === 30) evt('override_with_reason', noon, { reason: 'Wanted extra reasoning practice before an exam' });
    if (d === 33) evt('claim_rated', noon, { verdict: 'disagree', justified: true });
    if (d === 18) evt('pii_shared', noon, { kinds: 'phone number' });

    if (!rng.chance(p)) continue;
    const morning = rng.chance(0.65);
    const hour = morning ? 7.5 + rng.next() * 3.5 : 19 + rng.next() * 3;
    const stateShift = morning ? 0.18 : -0.15;
    let at = dayStart + Math.round(hour * 3600_000);

    const plan = generateDailyPlan(twin, sessions, goals, prefs, at, previous);
    plans.push(plan);
    previous = plan;
    if (rng.chance(0.12)) evt('plan_edited', at - 30_000);
    for (const item of plan.items) {
      const resp = rng.chance(0.1) ? 'modified' : 'accepted';
      const lowConf = item.mode === 'assessment';
      const viewed = rng.chance(0.15 + 0.35 * (d / 41));
      evt('recommendation_response', at - 10_000, { response: resp, confidence: lowConf ? 'low' : 'moderate', evidenceViewed: viewed });
      const s = run(item.dimension, item.mode, at, stateShift, { planItemId: item.id });
      item.done = true;
      item.sessionId = s.id;
      at = s.endedAt + 60_000;
    }

    // Conversations with the coach a few times a week.
    if (rng.chance(0.35)) {
      const clarifying = rng.chance(0.3 + 0.4 * (d / 41));
      evt('chat_question', at + 120_000, { clarifying, specificity: Math.round((0.3 + rng.next() * 0.7) * 100) / 100 });
      if (rng.chance(0.5)) evt('followup', at + 180_000);
    }
  }

  // Keep the coach-suggested goal open and slightly ahead of the learner, as in real use.
  const memNow = currentProfile(twin, now).find((x) => x.id === 'memory')!.summary.score;
  for (const g of goals) if (g.kind === 'score' && g.dimension === 'memory') g.target = Math.min(92, Math.max(g.target, Math.round(memNow + 7)));

  // Sanity: every session belongs to a known task.
  sessions.forEach((s) => getTask(s.taskId));
  return { twin, sessions, goals, plans: plans.slice(-14), events, prefs };
}

function startOfDay(ts: number): number {
  const d = new Date(ts);
  d.setHours(0, 0, 0, 0);
  return d.getTime();
}
